const ART_META = {"cast/whiskeyjack":{"lines":["Whiskeyjack","Ch 1 to 7","“All five. Keep doing that.”"],"ch":1},"cast/dujek_onearm":{"lines":["Dujek Onearm","Ch 7 · a voice through a bone","“You came up out of the Pale with all five. I noticed.”"],"ch":7},"cast/quick_ben":{"lines":["Quick Ben","Ch 1, 3, 4, 6, 7","“I'd try to be less interesting.”"],"ch":1},"cast/kalam":{"lines":["Kalam","Ch 1, 3, 4, 6, 7","“Go to sleep, Sergeant. You didn't see that.”"],"ch":1},"cast/fiddler":{"lines":["Fiddler","Ch 1, 3, 4, 6, 7","“I count. It looks like cheating to people who can't.”"],"ch":1},"cast/hedge":{"lines":["Hedge","Ch 1, 3, 6, 7","“You're wasted on the marines.”"],"ch":1},"cast/mallet":{"lines":["Mallet","Ch 3, 6, 7","“It wants days he won't give me.”"],"ch":3},"cast/trotts":{"lines":["Trotts","Ch 3, 6, 7","Bares his teeth. Brisk: “Him I like.”"],"ch":3},"cast/sorry":{"lines":["Sorry","Ch 3, 4 · Ch 7 as Apsalar","“Now stand somewhere I am not.”"],"ch":3},"cast/paran":{"lines":["Paran","Ch 1, 5, 6, 7","“You carried that a long way. It was heavier than it looked.”"],"ch":1},"cast/toc_the_younger":{"lines":["Toc the Younger","Ch 2, 5","“Tell him Toc kept riding. He'll know what it means.”"],"ch":2},"cast/tattersail":{"lines":["Tattersail","Prologue, Ch 1 · gone in Ch 2","“You came back with all five. That's a nice touch.”"],"ch":0},"cast/kruppe":{"lines":["Kruppe","Ch 3, 4, 6, 7","“Kruppe would go in threes, himself. Or sixes.”"],"ch":3},"cast/crokus":{"lines":["Crokus","Ch 3, 4, 6, 7","Spins Oponn's coin. “Nobody catches that.”"],"ch":3},"cast/rallick_nom":{"lines":["Rallick Nom","Ch 4, 6","“Go home, Malazan. This isn't your war.”"],"ch":4},"cast/coll":{"lines":["Coll","Ch 3, 5, 6, 7","“The Empire never conquers a city. It waits.”"],"ch":3},"cast/lorn_the_adjunct":{"lines":["Lorn, the Adjunct","Ch 2, 5, 6","She looked at you the way you'd look at a smudge on a map."],"ch":2},"cast/tool_the_imass":{"lines":["Tool","Ch 5, 7 · on the plain in 2, unnamed","“You are very small. Stay that way.”"],"ch":5},"cast/the_tall_guest":{"lines":["The tall guest","Ch 6 · never named","“I will second him.”"],"ch":6},"cast/crone_the_great_raven":{"lines":["Crone","Ch 2, 5, 7","“Keep counting.”"],"ch":2},"originals/the_grey_cloak":{"lines":["The grey cloak","Claw · Prologue to Ch 7","Clean boots. A very neat hand. A very good memory for sergeants.","“Three rounds, Sergeant. You held them. That's been noted.”"],"ch":0},"originals/madryn":{"lines":["Madryn","Claw handler · the dye-shop · Ch 3","Blue-dyed hands, a pot of tea, and your name in her best hand.","“I'll sit here and think about you.”"],"ch":3},"originals/vell":{"lines":["Vell","Guild journeyman · Ch 4, 7","Ocelot's clan. A rope man, and a black horn token that opens a door.","“Vell. Journeyman. I owe you.”"],"ch":4},"originals/ch_kess":{"lines":["Ch'kess","Black Moranth quartermaster · Ch 7","Two clicks and a hiss. Carries both rolls, the living and the dead.","“Spent is square.”"],"ch":7},"originals/pennick":{"lines":["Pennick","Gate clerk · the Worry Gate · Ch 3, 7","Writes “goat” in his margin when he doubts you. Keep to the right-hand side of the arch.","“I keep a column.”"],"ch":3},"originals/sethand":{"lines":["Sethand","Rhivi guide · the clan-mother's people · Ch 2, 5, 7","Sings over the dead horses, and gives the words to those he trusts.","“Come by the clan-mother's fires. Say my name.”"],"ch":2},"originals/moreau":{"lines":["Moreau","Deserter of the Second · Prologue, Ch 2","Garrow's man in the tunnels, and on a ridge at dusk. Never resolved.","“That's twice. Tell Garrow. Or don't.”"],"ch":0},"originals/quartermaster_pell":{"lines":["Quartermaster Pell","The Host's stores · Ch 1","Has one face and one word for everything. The mule is named for the face.","“Adequate.” · “Off the books. The books never liked you.”"],"ch":1},"originals/the_guild_veteran":{"lines":["The Guild veteran","Ocelot's man · Ch 4, 6, 7","Asks twice. Settles it, lets it lapse, or keeps it open, depending on you.","“Ocelot sends his regards.”"],"ch":4},"originals/pell_the_mule":{"lines":["Pell, the mule","Ch 2 to 7 · in the ledger","Bites Gadrobi. Left with the Paviors' Guild in lieu of wages. Brisk misses the mule.","Kettle: “It does the same face.”"],"ch":2}};
